public function isValidShop(): bool
{
    $shop = $this->getShopFromRequestAttributes();

    // 空の場合は本店の為、有効判定とする
    if ($shop === '') {
        return true;
    }

    $BaseInfo = $this->baseInfoRepository->findByHtmlClassName($shop);

    return $BaseInfo !== null
        ? true
        : false;
}

if (!$this->baseInfoService->isValidShop()) {
    // 店舗が見つからない場合は本店のデフォルトロケールにリダイレクト
    $event->setResponse(new RedirectResponse('/'.$this->defaultLocale.'/', Response::HTTP_MOVED_PERMANENTLY));
}

public function isShopByPath(?string $shopPath): bool
{
    $slug = ltrim((string) $shopPath, '/');
    if ($slug === '') {
        return false;
    }

    return $this->baseInfoRepository->findOneBy(['html_class_name' => $slug]) instanceof BaseInfo;
}
